// The webhook payload lands under .body; tolerate both shapes.
const r = $json.body ?? $json;
const s = r.summary ?? {};
const f = r.failures ?? [];

const esc = (v) => String(v ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const th = 'padding:7px 10px;border-bottom:2px solid #333;text-align:left';
const td = 'padding:7px 10px;border-bottom:1px solid #eee';

const rows = f.map((x) =>
  `<tr><td style="${td}"><b>${esc(x.what)}</b><br><span style="color:#888;font-size:12px">${esc(x.url)}</span></td>` +
  `<td style="${td};color:#c0392b">${esc(x.error)}</td>` +
  `<td style="${td};color:#888">${esc(x.server)}</td></tr>`).join('');

const formLine = s.forms
  ? `, ${s.formsOk}/${s.forms} lead form${s.forms === 1 ? '' : 's'} accepted a test submission`
  : '';

const body = r.healthy
  ? `<p>All <b>${s.sites}</b> hostnames answered${formLine}.</p>`
  : `<p><b style="color:#c0392b">${f.length} failing</b> of ${s.sites} hostnames${formLine}.</p>
     <table style="border-collapse:collapse;width:100%;font-size:13px">
       <thead><tr><th style="${th}">What</th><th style="${th}">Problem</th><th style="${th}">Server</th></tr></thead>
       <tbody>${rows}</tbody>
     </table>`;

const html = `<div style="font:14px/1.6 system-ui,-apple-system,'Segoe UI',sans-serif;color:#222;max-width:680px">
  <h2 style="margin:0 0 4px">KW Estate — outside-in check</h2>
  <p style="margin:0 0 18px;color:#888;font-size:13px">${esc(r.at)} · slowest response ${s.slowestMs ?? 0} ms</p>
  ${body}
  <p style="margin-top:22px;font-size:12px;color:#aaa">
    Sent by the KW Estate dashboard on srv1340120. Full detail at
    <a href="https://estate.leadq.co.in" style="color:#0d9c8a">estate.leadq.co.in</a>.
  </p>
</div>`;

return [{ json: { to: r.to, cc: r.cc ?? '', subject: r.subject, html, healthy: r.healthy === true } }];

const req = $('Verify webhook').first().json.body ?? {};
const phone = String(req.phone ?? '').replace(/\D/g, '').slice(-10);
const res = $json ?? {};

// Cratio does not always answer at the top level. An IP-allowlist rejection
// arrives as {"data":"\n{\"error\":\"You are not allowed...\"}"} — the real
// reply is a JSON STRING nested inside `data`. Unwrap before deciding, or a
// hard refusal reads as "no such lead".
let body = res;
if (typeof res?.data === 'string') {
  try { body = JSON.parse(res.data.trim()); } catch { body = { error: res.data.trim() }; }
}

// THREE outcomes, not two. A bad key, a wrong formname, an unknown field or a
// blocked IP all make Cratio return an error — and if that reads as "not
// found", a misconfigured lookup is indistinguishable from a lead that
// genuinely went missing, and the dashboard raises a critical alert about the
// wrong system entirely.
const err = body?.error ?? body?.Error ?? (Array.isArray(body) ? body[0]?.error : null);
if (err) {
  return [{ json: { result: 'LEAD_ERROR', checked: phone, detail: String(err).slice(0, 200) } }];
}

// {"success":[{"totalrows":N,"data":[...]}]} on a hit.
const rows = Number(body?.success?.[0]?.totalrows ?? 0);
const found = rows > 0 || (phone.length === 10 && JSON.stringify(body).includes(phone));

// A token, never the phone number itself: a not-found reply that echoed the
// value back would match the search string and read as a hit.
return [{ json: {
  result: found ? 'LEAD_FOUND' : 'LEAD_MISSING',
  checked: phone,
  rows,
  // Enough of the raw reply to diagnose the next problem without another run.
  detail: found ? undefined : JSON.stringify(body).slice(0, 200),
} }];
